// spec: specs/businessdetail-gallery.md (3.1–3.6) · кейсы: .qa/tests/businessdetail-gallery/GALLERY-11..16.md · тикет #d31f3b (PR #204)
// seed: tests/seed.spec.ts (гость) · прод, только просмотр: SW выкл, не-GET блокируются, cookie «חיוניים בלבד», PWA снузено.
// Устройства: @desktop (1440×900), @mobile (iPhone 13 Mini WebKit + Pixel 7 Chromium); Esc — @desktop, свайп — @android
// (CDP touch; на iPhone/WebKit свайп не эмулируется — программист: «Safari — только стрелки»).
// Лайтбокс: role=dialog fixed inset-0 bg-black; стрелки «התמונה הבאה» (слева) / «התמונה הקודמת» (справа), по кругу;
// счётчик «N/M» (aria-live) вверху слева; «סגירה» (X) вверху справа; только картинки (видео не входит).
import { test, expect } from '@playwright/test';
import {
  prepare, openListing, settledImage, readWindow, nextArrow, LISTINGS, LOAD, PX_TOL,
  fullscreenButton, lightbox, lbCounter, lbNext, lbPrev, lbClose, openLightbox, settledLightbox, readLightbox,
  expectFullscreenContain, touchSwipe,
} from './gallery.helpers';

test.use({ serviceWorkers: 'block' });

const N = LISTINGS.mixed.count; // «משתלה» — 4 картинки, видео нет
const DEVICES = ['@desktop', '@mobile'] as const;

/** Открыть «משתלה» и дождаться первой картинки в окне. Нет нескольких картинок — skip (данные прода). */
async function openMixed(page: import('@playwright/test').Page) {
  await openListing(page, LISTINGS.mixed.id);
  const s = await settledImage(page, 'картинка 1 на странице');
  test.skip(!(await nextArrow(page).count()), 'в объявлении «משתלה» больше нет нескольких картинок — данные прода');
  return s;
}

/** Лайтбокс закрыт: диалога нет, прокрутка страницы разблокирована, scrollY прежний. */
async function expectClosed(page: import('@playwright/test').Page, y0: number, label: string) {
  await expect(lightbox(page), `${label}: лайтбокс закрылся`).toHaveCount(0, LOAD);
  await expect.poll(() => page.evaluate(() => getComputedStyle(document.body).overflow), { message: `${label}: прокрутка страницы разблокирована` }).not.toBe('hidden');
  expect(Math.abs((await readWindow(page)).scrollY - y0), `${label}: scrollY ${y0} не изменился`).toBeLessThanOrEqual(1);
}

for (const dev of DEVICES) {
  test.describe(`Галерея: полноэкранный просмотр ${dev}`, () => {
    test.beforeEach(async ({ page }) => {
      await prepare(page);
    });

    test(`клик по картинке — лайтбокс на весь экран на чёрном, картинка целиком, счётчик 1/${N}, X #d31f3b ${dev} @prod-safe`, async ({ page }) => {
      await openMixed(page);
      const y0 = (await readWindow(page)).scrollY;
      await openLightbox(page);
      const s = await settledLightbox(page, 1, N, 'открыт');
      expectFullscreenContain(s, 'картинка 1');
      expect(s.bodyOverflow, 'прокрутка страницы под лайтбоксом заблокирована').toBe('hidden');
      expect(Math.abs(s.scrollY - y0), `scrollY ${y0} не изменился при открытии`).toBeLessThanOrEqual(1);
      // RTL-раскладка: X — вверху справа, счётчик — вверху слева.
      const close = await lbClose(page).boundingBox();
      const counter = await lbCounter(page).boundingBox();
      expect(close, 'кнопка X «סגירה» видна').not.toBeNull();
      expect(close!.x + close!.width / 2, 'X в правой половине экрана').toBeGreaterThan(s.vw / 2);
      expect(close!.y, 'X вверху экрана').toBeLessThan(100);
      expect(counter!.x + counter!.width / 2, 'счётчик в левой половине экрана').toBeLessThan(s.vw / 2);
      expect(counter!.y, 'счётчик вверху экрана').toBeLessThan(100);
    });

    test(`стрелки листают по кругу — счётчик и картинка меняются, каждая целиком #d31f3b ${dev} @prod-safe`, async ({ page }) => {
      await openMixed(page);
      await openLightbox(page);
      let s = await settledLightbox(page, 1, N, 'открыт');
      // RTL: «התמונה הבאה» — слева, «התמונה הקודמת» — справа.
      const nb = await lbNext(page).boundingBox();
      const pb = await lbPrev(page).boundingBox();
      expect(nb!.x + nb!.width / 2, '«התמונה הבאה» в левой половине').toBeLessThan(s.vw / 2);
      expect(pb!.x + pb!.width / 2, '«התמונה הקודמת» в правой половине').toBeGreaterThan(s.vw / 2);

      const alts = [s.img!.alt];
      for (let i = 2; i <= N; i++) {
        await lbNext(page).click();
        s = await settledLightbox(page, i, N, `› ${i}`);
        expectFullscreenContain(s, `картинка ${i}`);
        alts.push(s.img!.alt);
      }
      expect(new Set(alts).size, `пролистаны ${N} разных картинок`).toBe(N);
      await lbNext(page).click();
      s = await settledLightbox(page, 1, N, `› с последней — по кругу на 1`);
      expect(s.img!.alt).toBe(alts[0]);
      await lbPrev(page).click();
      s = await settledLightbox(page, N, N, `‹ с первой — по кругу на ${N}`);
      expect(s.img!.alt).toBe(alts[N - 1]);
      await lbPrev(page).click();
      s = await settledLightbox(page, N - 1, N, `‹ ${N - 1}`);
      expectFullscreenContain(s, `картинка ${N - 1}`);
    });

    test(`открывается на текущей картинке страницы, после закрытия X окно на последней просмотренной #d31f3b ${dev} @prod-safe`, async ({ page }) => {
      let w = await openMixed(page);
      await nextArrow(page).click();
      w = await settledImage(page, 'картинка 2 на странице', w.img!.src);
      const y0 = w.scrollY;
      await openLightbox(page);
      await settledLightbox(page, 2, N, 'открыт на картинке 2');
      await lbNext(page).click();
      const s = await settledLightbox(page, 3, N, '› 3');
      await lbClose(page).click();
      await expectClosed(page, y0, 'X');
      await expect
        .poll(async () => (await readWindow(page)).img?.alt ?? '', { ...LOAD, message: `окно на странице показывает последнюю просмотренную «${s.img!.alt}»` })
        .toBe(s.img!.alt);
      await expect(fullscreenButton(page), 'окно снова открывает лайтбокс').toBeVisible();
    });

    test(`одна картинка и видео — видео не в лайтбоксе, счётчик 1/1, стрелок нет #d31f3b ${dev} @prod-safe`, async ({ page }) => {
      await openListing(page, LISTINGS.video.id);
      await expect(page.locator('video').first(), 'слайд 1 — видео').toBeVisible(LOAD);
      await expect(fullscreenButton(page), 'на слайде с видео нет кнопки полноэкранного просмотра').toHaveCount(0);
      test.skip(!(await nextArrow(page).count()), 'в объявлении больше нет второго слайда — данные прода');
      await nextArrow(page).click();
      await settledImage(page, 'картинка на странице');
      await openLightbox(page);
      const total = (await lbCounter(page).textContent())?.split('/')[1];
      test.skip(total !== '1', `в объявлении теперь ${total} картинок — данные прода`);
      const s = await settledLightbox(page, 1, 1, 'одна картинка', false);
      expectFullscreenContain(s, 'одна картинка');
      expect(s.videos, 'в лайтбоксе нет видео').toBe(0);
      await expect(lbNext(page), 'стрелки «התמונה הבאה» нет').toHaveCount(0);
      await expect(lbPrev(page), 'стрелки «התמונה הקודמת» нет').toHaveCount(0);
      await lbClose(page).click();
      await expect(lightbox(page), 'лайтбокс закрылся').toHaveCount(0, LOAD);
    });
  });
}

test.describe('Галерея: полноэкранный просмотр — клавиатура @desktop', () => {
  test.beforeEach(async ({ page }) => {
    await prepare(page);
  });

  test(`Esc закрывает лайтбокс, страница на месте (scrollY 100) #d31f3b @desktop @prod-safe`, async ({ page }) => {
    await openMixed(page);
    await page.evaluate(() => window.scrollTo(0, 100));
    await expect.poll(() => page.evaluate(() => window.scrollY), { message: 'страница прокручена на 100' }).toBe(100);
    await openLightbox(page);
    await settledLightbox(page, 1, N, 'открыт');
    expect(Math.abs((await readLightbox(page)).scrollY - 100), 'scrollY 100 при открытом лайтбоксе').toBeLessThanOrEqual(PX_TOL);
    await page.keyboard.press('Escape');
    await expectClosed(page, 100, 'Esc');
  });
});

test.describe('Галерея: полноэкранный просмотр — свайп @android', () => {
  test.beforeEach(async ({ page }) => {
    await prepare(page);
  });

  test(`свайп листает: палец слева направо — следующая, справа налево — предыдущая (RTL) #d31f3b @android @prod-safe`, async ({ page }) => {
    await openMixed(page);
    await openLightbox(page);
    const s = await settledLightbox(page, 1, N, 'открыт');
    const left = Math.round(s.vw * 0.2);
    const right = Math.round(s.vw * 0.8);
    await touchSwipe(page, left, right);
    expectFullscreenContain(await settledLightbox(page, 2, N, 'свайп слева направо → 2'), 'картинка 2');
    await touchSwipe(page, right, left);
    expectFullscreenContain(await settledLightbox(page, 1, N, 'свайп справа налево → 1'), 'картинка 1');
  });
});
